mapper.select:
SELECT COALESCE(MAX(version), 0) + 1
FROM layout_versions
WHERE layout_id = #{layoutId}

SELECT id, floor_plan_id, created_by, current_version_id, title, description, created_at FROM layouts
AND created_by = #{createdBy}
AND title LIKE CONCAT('%', #{query}, '%')
ORDER BY id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM layouts
AND created_by = #{createdBy}
AND title LIKE CONCAT('%', #{query}, '%')

mapper.update:
UPDATE layouts
SET title = #{title},
    description = #{description}
WHERE id = #{id}

UPDATE layouts
SET current_version_id = #{currentVersionId}
WHERE id = #{id}

UPDATE layout_versions
SET optimistic_lock = #{nextLock}
WHERE id = #{id}
  AND optimistic_lock = #{expectedLock}
  AND status = '초안'

mapper.select:
SELECT lv.layout_id AS layoutId, COUNT(*) AS simulationCount FROM simulations s JOIN layout_versions lv ON s.layout_version_id = lv.id WHERE lv.layout_id IN
#{layoutId}
GROUP BY lv.layout_id
